// Degree-12 Horner polynomial, mod 2^16, FULLY PIPELINED (one register per
// stage, with the input stage being a separate register independent of the
// pipeline -> higher Fmax). Same function as the reference, different
// instantiation.
module poly12_v15_8b (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg [15:0] r0, r1, r2, r3, r4, r5, r6, r7, r8, r9, r10, r11, r12;
    always @(posedge clk) begin
        if (!rst_n) begin r0 <= 16'd0; r1 <= 16'd0; r2 <= 16'd0; r3 <= 16'd0; r4 <= 16'd0; r5 <= 16'd0; r6 <= 16'd0; r7 <= 16'd0; r8 <= 16'd0; r9 <= 16'd0; r10 <= 16'd0; r11 <= 16'd0; r12 <= 16'd0; y <= 16'd0; end
        else begin
            r0 <= 16'd48;
            r1 <= r0 * x + 16'd24;
            r2 <= r1 * x + 16'd79;
            r3 <= r2 * x + 16'd2;
            r4 <= r3 * x + 16'd46;
            r5 <= r4 * x + 16'd35;
            r6 <= r5 * x + 16'd44;
            r7 <= r6 * x + 16'd66;
            r8 <= r7 * x + 16'd80;
            r9 <= r8 * x + 16'd64;
            r10 <= r9 * x + 16'd18;
            r11 <= r10 * x + 16'd58;
            r12 <= r11 * x + 16'd51;
            y <= r12;
        end
    end
endmodule
